import { MakeLogicType, actions, connect, kea, listeners, path, reducers, selectors } from 'kea'

import { teamLogic } from 'scenes/teamLogic'

import type { TeamPublicType, TeamType } from '~/types'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureFlagRequestListsLogicValues {
    currentTeam: TeamPublicType | TeamType | null // teamLogic
    currentTeamLoading: boolean // teamLogic
    allowedHosts: string[]
    allowedIps: string[]
    blockedHosts: string[]
    blockedIps: string[]
    firstAllowedIps: string[] | null
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureFlagRequestListsLogicActions {
    updateCurrentTeam: (payload: Partial<TeamType>) => Partial<TeamType> // teamLogic
    cancelFirstAllowedIps: () => {
        value: true
    }
    confirmFirstAllowedIps: (allowedIps: string[]) => {
        allowedIps: string[]
    }
    requestFirstAllowedIps: (allowedIps: string[]) => {
        allowedIps: string[]
    }
    saveAllowedIps: (allowedIps: string[]) => {
        allowedIps: string[]
    }
    setAllowedHosts: (allowedHosts: string[]) => {
        allowedHosts: string[]
    }
    setAllowedIps: (allowedIps: string[]) => {
        allowedIps: string[]
    }
    setBlockedHosts: (blockedHosts: string[]) => {
        blockedHosts: string[]
    }
    setBlockedIps: (blockedIps: string[]) => {
        blockedIps: string[]
    }
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface featureFlagRequestListsLogicMeta {
    __keaTypeGenInternalSelectorTypes: {
        blockedHosts: (currentTeam: TeamPublicType | TeamType | null) => string[]
        blockedIps: (currentTeam: TeamPublicType | TeamType | null) => string[]
        allowedHosts: (currentTeam: TeamPublicType | TeamType | null) => string[]
        allowedIps: (currentTeam: TeamPublicType | TeamType | null) => string[]
    }
}

export type featureFlagRequestListsLogicType = MakeLogicType<
    featureFlagRequestListsLogicValues,
    featureFlagRequestListsLogicActions,
    Record<string, any>,
    featureFlagRequestListsLogicMeta
>

export const featureFlagRequestListsLogic = kea<featureFlagRequestListsLogicType>([
    path(['products', 'feature_flags', 'frontend', 'featureFlagRequestListsLogic']),
    connect(() => ({
        values: [teamLogic, ['currentTeam', 'currentTeamLoading']],
        actions: [teamLogic, ['updateCurrentTeam']],
    })),
    actions({
        setBlockedHosts: (blockedHosts: string[]) => ({ blockedHosts }),
        setBlockedIps: (blockedIps: string[]) => ({ blockedIps }),
        setAllowedHosts: (allowedHosts: string[]) => ({ allowedHosts }),
        setAllowedIps: (allowedIps: string[]) => ({ allowedIps }),
        saveAllowedIps: (allowedIps: string[]) => ({ allowedIps }),
        requestFirstAllowedIps: (allowedIps: string[]) => ({ allowedIps }),
        cancelFirstAllowedIps: true,
        confirmFirstAllowedIps: (allowedIps: string[]) => ({ allowedIps }),
    }),
    reducers({
        firstAllowedIps: [
            null as string[] | null,
            {
                confirmFirstAllowedIps: () => null,
                cancelFirstAllowedIps: () => null,
                requestFirstAllowedIps: (_, { allowedIps }) => allowedIps,
            },
        ],
    }),
    selectors({
        blockedHosts: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string[] =>
                currentTeam?.feature_flag_policy_config?.blocked_hosts ?? [],
        ],
        blockedIps: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string[] =>
                currentTeam?.feature_flag_policy_config?.blocked_ips ?? [],
        ],
        allowedHosts: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string[] =>
                currentTeam?.feature_flag_policy_config?.allowed_hosts ?? [],
        ],
        allowedIps: [
            (s) => [s.currentTeam],
            (currentTeam: TeamPublicType | TeamType | null): string[] =>
                currentTeam?.feature_flag_policy_config?.allowed_ips ?? [],
        ],
    }),
    listeners(({ actions, values }) => ({
        // Send only the edited list. The API keeps a list the request leaves out, so a save
        // here does not overwrite a newer change to the other list with the value this page loaded.
        setBlockedHosts: ({ blockedHosts }) => {
            actions.updateCurrentTeam({ feature_flag_policy_config: { blocked_hosts: blockedHosts } })
        },
        setBlockedIps: ({ blockedIps }) => {
            actions.updateCurrentTeam({ feature_flag_policy_config: { blocked_ips: blockedIps } })
        },
        setAllowedHosts: ({ allowedHosts }) => {
            actions.updateCurrentTeam({ feature_flag_policy_config: { allowed_hosts: allowedHosts } })
        },
        // The first allowed IP address refuses every other caller as soon as it saves.
        setAllowedIps: ({ allowedIps }) => {
            if (values.allowedIps.length === 0 && allowedIps.length > 0) {
                actions.requestFirstAllowedIps(allowedIps)
            } else {
                actions.saveAllowedIps(allowedIps)
            }
        },
        confirmFirstAllowedIps: ({ allowedIps }) => {
            actions.saveAllowedIps(allowedIps)
        },
        saveAllowedIps: ({ allowedIps }) => {
            actions.updateCurrentTeam({ feature_flag_policy_config: { allowed_ips: allowedIps } })
        },
    })),
])
